INSERT INTO subjects (id, name, icon, color, description, "createdAt") VALUES
('aplikasi-skrining', 'Aplikasi Skrining', 'Search', 'emerald', 'Metodologi dan aplikasi uji tapis penapisan penyakit secara cepat dan andal pada populasi sehat.', '2026-06-01T00:00:00Z'),
('survei-cepat-epi', 'Survei Cepat Epidemiologi', 'Zap', 'sky', 'Metode pengumpulan data lapangan dengan teknik klaster 30x7 secara taktis, cepat, dan ekonomis.', '2026-06-01T00:00:00Z'),
('p-surveilans-epi', 'Praktikum Surveilans Epidemiologi', 'Activity', 'indigo', 'Pengamatan sistematis terus-menerus terhadap distribusi penyakit melalui instrumen SKDR puskesmas.', '2026-06-01T00:00:00Z'),
('manajemen-analisis-data', 'Manajemen dan Analisis Data Epidemiologi', 'Database', 'purple', 'Prinsip pengolahan data murni kesehatan, pembersihan variabel, regresi linear, dan estimasi Odd Ratio / RR.', '2026-06-01T00:00:00Z'),
('telaah-ilmiah', 'Telaah Ilmiah Epidemiologi', 'BookOpen', 'pink', 'Kritik akademis jurnal ilmiah kesehatan, mendeteksi bias riset, dan menyusun sintesis PICO.', '2026-06-01T00:00:00Z'),
('epi-penyakit-tropis', 'Epidemiologi Penyakit Tropis', 'Shield', 'amber', 'Studi persebaran, pencegahan, dan pola inang-vektor dari penyakit khas tropis seperti DBD, Malaria, dan TB.', '2026-06-01T00:00:00Z'),
('praktik-investigasi-wabah', 'Praktik Investigasi Wabah', 'Flame', 'rose', 'Langkah taktis penyelidikan kejadian luar biasa (KLB), melacak kurva epidemi, dan klasterisasi kasus.', '2026-06-01T00:00:00Z')
INSERT INTO materials (id, "subjectId", title, content, points, formulas, flashcards, "createdAt") VALUES
('m1', 'aplikasi-skrining', 'Validitas Alat Uji Tapis Skrining', 'Uji skrining dirancang untuk mendeteksi dini penyakit pada individu asimtomatik (tanpa gejala klinis). Instrumen skrining dinilai berdasarkan validitas (Sensitivitas & Spesifisitas) serta keandalan (Reliabilitas).', '{"Sensitivitas: Proporsi orang sakit sesungguhnya yang tes skriningnya positif.","Spesifisitas: Proporsi orang sehat sesungguhnya yang tes skriningnya menunjukkan hasil negatif.","False Positive: Hasil tes menunjukkan positif padahal aslinya individu sehat."}', '{"Sensitivitas = True Positive / (True Positive + False Negative)","Spesifisitas = True Negative / (True Negative + False Positive)","Nilai Prediktif Positif = True Positive / (True Positive + False Positive)"}', '[{"id":"fc-m1-1","question":"Apa perbedaan mendasar antara Skrining dengan Diagnosis?","answer":"Skrining diuji pada kelompok populasi sehat tanpa gejala, sedangkan Diagnosis pada pasien suspek bergejala.","level":0},{"id":"fc-m1-2","question":"Tuliskan rumus Sensitivitas alat uji skrining!","answer":"Sensitivitas = True Positive / (True Positive + False Negative)","level":0},{"id":"fc-m1-3","question":"Apa konsekuensi utama jika sensitivitas tes skrining terlalu rendah?","answer":"Banyak orang sakit yang lolos saringan (False Negative tinggi), menyebabkan kegagalan deteksi dini penyakit.","level":0}]', '2026-06-01T00:00:00Z'),
('m2', 'survei-cepat-epi', 'Metode Klaster Dua Tahap WHO 30x7', 'Survei Cepat Epidemiologi (Rapid Epidemiological Assessment) adalah metode taktis lapangan untuk mendapatkan estimasi cakupan program imunisasi atau status gizi dengan waktu pengerjaan yang singkat dan biaya rendah.', '{"Menggunakan teknik sampling klaster dua tahap konvensional.","Tahap 1: Memilih 30 klaster pemukiman secara Probability Proportional to Size (PPS).","Tahap 2: Memilih secara acak sederhana minimal 7 responden per klaster.","Total ukuran sampel minimal adalah 210 responden untuk menjamin ketepatan estimasi."}', '{"Total Responden = 30 Klaster * 7 Responden = 210 Orang","Interval Kumulatif (untuk pemilihan klaster PPS) = Total Populasi / 30"}', '[{"id":"fc-m2-1","question":"Mengapa metode survei cepat 30x7 banyak dipilih di wilayah tropis miskin?","answer":"Karena tidak membutuhkan peta sampling lengkap di awal, sangat hemat biaya, dan cepat diselesaikan di lapangan.","level":0},{"id":"fc-m2-2","question":"Berapakah jumlah standar minimum responden klaster menurut pedoman WHO?","answer":"Minimal 210 responden (Didapat dari 30 Klaster ditiap klaster terdapat 7 responden).","level":0}]', '2026-06-01T00:00:00Z'),
('m3', 'p-surveilans-epi', 'Mekanisme SKDR di Puskesmas', 'Sistem Kewaspadaan Dini dan Respon (SKDR) dirancang untuk memantau tren penyakit menular berpotensi wabah secara mingguan guna segera memicu respon penanggulangan jika alarm terlewati.', '{"Laporan wajib dikirim secara mingguan (setiap hari Senin/Selasa pagi).","Variabel umum mencakup tren demam akut, diare akut, ILI (Influenza Like Illness), dan suspek campak.","Indikator kualitas surveilans: Kelengkapan (completeness) dan Ketepatan waktu (promptness)."}', '{"Kelengkapan (%) = (Jumlah Puskesmas Melapor / Total Target Puskesmas) * 100%","Ketepatan Laporan (%) = (Jumlah Laporan Tepat Waktu / Total Target Laporan) * 100%"}', '[{"id":"fc-m3-1","question":"Apa singkatan dari instrumen SKDR?","answer":"Sistem Kewaspadaan Dini dan Respon (sistem pendeteksian dini potensi wabah mingguan).","level":0},{"id":"fc-m3-2","question":"Sebutkan 3 penyakit utama yang wajib dipantau dalam lembar SKDR!","answer":"Diare Akut, Influenza Like Illness (ILI), Demam Berdarah Dengue (DBD), atau Demam Tifoid.","level":0}]', '2026-06-01T00:00:00Z'),
('m4', 'manajemen-analisis-data', 'Ukuran Kekuatan Hubungan: Odd Ratio (OR) dan Relative Risk (RR)', 'Manajemen analisis epidemiologi membedakan asosiasi berdasarkan desain studi. Studi Kasus Kontrol dianalisis dengan Odd Ratio, sedangkan Studi Kohort dianalisis dengan Relative Risk.', '{"Tabel Kontingensi 2x2 digunakan untuk merepresentasikan paparan (Exposure) dan luaran (Disease).","OR menggambarkan kemungkinan terpapar pada kelompok kasus dibanding kelompok kontrol.","Confounding adalah variabel luar yang memiliki hubungan baik dengan faktor paparan maupun disease."}', '{"Odds Ratio (OR) = (a * d) / (b * c) [Dimana a=kasus terpapar, d=kontrol tidak terpapar]","Relative Risk (RR) = [a / (a + b)] / [c / (c + d)] (mengukur insidensi kelompok terpapar vs tidak terpapar)"}', '[{"id":"fc-m4-1","question":"Kapankah kita menggunakan Odds Ratio (OR) alih-alih Relative Risk (RR)?","answer":"Saat desain penelitian yang kita gunakan adalah Case-Control (Kasus-Kontrol), di mana angka insidensi sesungguhnya tidak bisa dihitung.","level":0},{"id":"fc-m4-2","question":"Apakah yang dimaksud dengan Confounding Factor dalam analisis data?","answer":"Variabel perancu yang bias mengaburkan hubungan asosiasi sebenarnya antara paparan utama dan penyakit.","level":0}]', '2026-06-01T00:00:00Z'),
('m5', 'telaah-ilmiah', 'Critical Appraisal Artikel Jurnal Epidemiologi', 'Melakukan penelaahan kritis terhadap literatur kedokteran dan kesehatan masyarakat agar tidak terjebak hasil penelitian semu yang disebabkan kesalahan desain riset.', '{"Menggunakan panduan baku kritisi (misalnya kuesioner CASP atau STROBE).","Mengevaluasi validitas internal (metodologi bebas bias) dan validitas eksternal (generalisasi populasi).","Pernyataan PICO membantu merumuskan komponen telaah secara cepat."}', '{"PICO = Population / Patient, Intervention / Exposure, Comparison / Control, Outcome"}', '[{"id":"fc-m5-1","question":"Sebutkan 3 jenis bias utama yang harus dievaluasi saat menelaah jurnal!","answer":"Selection Bias (bias seleksi sampel), Information/Measurement Bias (bias informasi), dan Confounding Bias.","level":0},{"id":"fc-m5-2","question":"Apakah urutan teratas bukti ilmiah (Highest Hierarchy of Evidence)?","answer":"Systematic Review / Meta-analysis dari Randomised Controlled Trials (RCT).","level":0}]', '2026-06-01T00:00:00Z'),
('m7', 'praktik-investigasi-wabah', 'Sepuluh Langkah Investigasi KLB CDC', 'Investigasi wabah adalah penyelidikan lapangan yang dirancang untuk melacak penyebab kejadian luar biasa (KLB) penyakit agar tindakan isolasi dan penghentian paparan segera diambil.', '{"Langkah paling awal adalah mempersiapkan kerja lapangan dan memverifikasi diagnosis.","Mendefinisikan kasus secara ketat (Confirm Case, Probable Case, Suspect Case).","Menggambar Kurva Epidemi (Epidemic Curve) berdasarkan waktu timbul gejala pasien."}', '{"Attack Rate (%) = (Jumlah kasus baru pada selang waktu tertentu / Jumlah populasi berisiko) * 100%","Case Fatality Rate (CFR %) = (Jumlah kematian akibat penyakit tersebut / Total kasus penyakit tersebut) * 100%"}', '[{"id":"fc-m7-1","question":"Apakah perbedaan bentuk kurva epidemi tipe Point Source dibanding Propagated Source?","answer":"Point Source menunjukkan satu lonjakan puncak tunggal yang cepat mereda; Propagated menunjukkan serangkaian puncak beruntun seiring penularan sekunder orang-ke-orang.","level":0},{"id":"fc-m7-2","question":"Apa ukuran mortalitas klinis utama dari tingkat keganasan wabah?","answer":"Case Fatality Rate (CFR) = (Jumlah meninggal / Jumlah kasus terdiagnosis) * 100%.","level":0}]', '2026-06-01T00:00:00Z'),
('m8', 'epi-penyakit-tropis', 'Bu Arlina - Kelompok 1 - Filariasis', 'Filariasis atau penyakit kaki gajah adalah penyakit infeksi menahun akibat cacing filaria yang menyerang sistem limfatik. Penularan terjadi melalui gigitan nyamuk yang membawa larva infektif. Penyakit ini dapat menyebabkan pembengkakan kronis pada tungkai, lengan, atau organ tubuh lain. Pengendalian dilakukan melalui pengobatan massal, pengobatan kasus, serta pencegahan vektor.', '{"Filariasis","Penyakit kaki gajah","Infeksi cacing filaria","Ditularkan nyamuk","Menyerang sistem limfatik","Wuchereria bancrofti","Brugia malayi","Brugia timori","Larva L3","Mikrofilaria","Limfedema","Elephantiasis","Hidrokel","DEC","Albendazol","Pencegahan vektor"}', '{"3 spesies utama = W.bancrofti + B.malayi + B.timori","Penularan = Nyamuk → Larva L3 → Manusia","Kronis = Limfedema + Elephantiasis + Hidrokel","Pencegahan = 3M + Kelambu + Obat nyamuk","Terapi = DEC + Albendazol"}', '[{"id":"fc-m8-1","question":"Apa itu Filariasis?","answer":"Penyakit infeksi menahun akibat cacing filaria yang menyerang sistem limfatik.","level":0},{"id":"fc-m8-2","question":"Bagaimana filariasis ditularkan?","answer":"Melalui gigitan nyamuk yang membawa larva infektif.","level":0},{"id":"fc-m8-3","question":"Mengapa filariasis disebut penyakit kaki gajah?","answer":"Karena dapat menyebabkan pembengkakan besar pada tungkai.","level":0},{"id":"fc-m8-4","question":"Apa penyebab utama filariasis pada manusia?","answer":"Cacing filaria.","level":0},{"id":"fc-m8-5","question":"Sebutkan 3 spesies penyebab filariasis!","answer":"Wuchereria bancrofti, Brugia malayi, Brugia timori.","level":0},{"id":"fc-m8-6","question":"Stadium larva infektif filariasis adalah?","answer":"Larva stadium L3.","level":0},{"id":"fc-m8-7","question":"Apa dua inang dalam siklus hidup filariasis?","answer":"Manusia dan nyamuk.","level":0},{"id":"fc-m8-8","question":"Apa gejala fase akut filariasis?","answer":"Demam berulang, adenitis, limfangitis.","level":0},{"id":"fc-m8-9","question":"Apa manifestasi kronis filariasis?","answer":"Limfedema, elephantiasis, hidrokel.","level":0},{"id":"fc-m8-10","question":"Obat utama program eliminasi filariasis?","answer":"Dietilkarbamazin (DEC) dan Albendazol.","level":0},{"id":"fc-m8-11","question":"Berapa prevalensi filariasis Indonesia tahun 2023?","answer":"1,5%.","level":0},{"id":"fc-m8-12","question":"Provinsi dengan prevalensi tertinggi filariasis?","answer":"Papua Tengah.","level":0},{"id":"fc-m8-13","question":"Bagaimana cara pencegahan filariasis?","answer":"3M, kelambu, obat nyamuk, kebersihan diri.","level":0},{"id":"fc-m8-14","question":"Apa itu mikrofilaria?","answer":"Bentuk larva yang beredar di darah.","level":0},{"id":"fc-m8-15","question":"Apa tujuan pengobatan massal filariasis?","answer":"Memutus rantai penularan.","level":0}]', '2026-06-03T00:00:00Z'),
('m9', 'epi-penyakit-tropis', 'Bu Arlina - Kelompok 2 - Chikungunya', 'Chikungunya adalah penyakit infeksi virus yang disebabkan oleh Virus Chikungunya (CHIKV) dan ditularkan melalui gigitan nyamuk Aedes, terutama Aedes aegypti dan Aedes albopictus. Penyakit ini ditandai dengan demam tinggi mendadak, nyeri sendi berat, dan ruam kulit. Penanganan bersifat simptomatik karena belum tersedia antivirus khusus, sedangkan pencegahan difokuskan pada pengendalian vektor dan penerapan 3M Plus.', '{"Virus Chikungunya","CHIKV","Togaviridae","Alphavirus","Aedes aegypti","Aedes albopictus","Demam tinggi","Nyeri sendi berat","Ruam makulopapular","RT-PCR","IgM","IgG","Masa inkubasi 4-7 hari","3M Plus","PSN","Jumantik","Paracetamol","Viremia"}', '{"CHIKV = Virus penyebab Chikungunya","Penularan = Aedes → Manusia → Aedes","Masa tunas manusia = 4-7 hari","Masa tunas nyamuk = 8-10 hari","Diagnosis akut = RT-PCR hari 1-5","Pencegahan = 3M Plus + PSN + Jumantik"}', '[{"id":"fc-m9-1","question":"Apa penyebab penyakit Chikungunya?","answer":"Virus Chikungunya (CHIKV).","level":0},{"id":"fc-m9-2","question":"Virus Chikungunya termasuk famili apa?","answer":"Togaviridae.","level":0},{"id":"fc-m9-3","question":"Genus virus Chikungunya adalah?","answer":"Alphavirus.","level":0},{"id":"fc-m9-4","question":"Apa vektor utama penularan Chikungunya?","answer":"Nyamuk Aedes.","level":0},{"id":"fc-m9-5","question":"Dua spesies nyamuk utama penular Chikungunya?","answer":"Aedes aegypti dan Aedes albopictus.","level":0},{"id":"fc-m9-6","question":"Apa gejala khas Chikungunya?","answer":"Demam tinggi mendadak and nyeri sendi berat.","level":0},{"id":"fc-m9-7","question":"Selain demam dan nyeri sendi, gejala lain Chikungunya?","answer":"Ruam kulit, sakit kepala, dan nyeri otot.","level":0},{"id":"fc-m9-8","question":"Berapa masa inkubasi Chikungunya pada manusia?","answer":"4 sampai 7 hari.","level":0},{"id":"fc-m9-9","question":"Berapa masa tunas virus dalam nyamuk?","answer":"8 sampai 10 hari.","level":0},{"id":"fc-m9-10","question":"Kapan RT-PCR digunakan pada Chikungunya?","answer":"Fase akut hari 1 sampai 5.","level":0},{"id":"fc-m9-11","question":"Kapan antibodi IgM mulai muncul?","answer":"Setelah hari ke-5.","level":0},{"id":"fc-m9-12","question":"Apakah ada antivirus khusus Chikungunya?","answer":"Belum ada antivirus khusus.","level":0},{"id":"fc-m9-13","question":"Obat yang dianjurkan untuk demam dan nyeri Chikungunya?","answer":"Paracetamol.","level":0},{"id":"fc-m9-14","question":"Mengapa aspirin dan ibuprofen dihindari?","answer":"Karena harus dipastikan bukan DBD terlebih dahulu.","level":0},{"id":"fc-m9-15","question":"Bagaimana pencegahan Chikungunya?","answer":"3M Plus, PSN, dan pengendalian sarang nyamuk.","level":0},{"id":"fc-m9-16","question":"Apa arti 3M Plus?","answer":"Menguras, Menutup, Mendaur ulang, serta perlindungan tambahan dari nyamuk.","level":0},{"id":"fc-m9-17","question":"Apa itu siklus urban Chikungunya?","answer":"Penularan manusia ke nyamuk lalu kembali ke manusia.","level":0},{"id":"fc-m9-18","question":"Kelompok berisiko mengalami Chikungunya berat?","answer":"Bayi baru lahir, lansia, dan penderita penyakit kronis.","level":0},{"id":"fc-m9-19","question":"Apa itu viremia pada Chikungunya?","answer":"Kondisi saat virus berada dalam darah dan dapat ditularkan ke nyamuk.","level":0},{"id":"fc-m9-20","question":"Gerakan pencegahan berbasis rumah tangga untuk Chikungunya?","answer":"1 rumah 1 jumantik.","level":0}]', '2026-06-03T00:00:00Z'),
('m10', 'epi-penyakit-tropis', 'Bu Arlina - Kelompok 3 - Kusta', 'Kusta atau Leprosy adalah penyakit infeksi kronis yang disebabkan oleh bakteri Mycobacterium leprae yang menyerang kulit, saraf tepi, mata, dan mukosa saluran napas atas. Penularan terjadi melalui droplet pada kontak erat dan berlangsung lama. Penyakit ini berkembang lambat, tetapi dapat menyebabkan gangguan saraf, mati rasa, hingga kecacatan jika tidak diobati. Pengobatan utama menggunakan Multi Drug Therapy (MDT).', '{"Kusta","Leprosy","Mycobacterium leprae","Mycobacterium lepromatosis","Droplet","Kontak erat","Mati rasa","Saraf perifer","Sel Schwann","Makrofag","PB","MB","MDT","Bercak kulit mati rasa","Penebalan saraf","Kortikosteroid","Fisioterapi","Pencegahan stigma"}', '{"Penyebab = Mycobacterium leprae","Penularan = Droplet + Kontak erat lama","Diagnosis WHO = Bercak mati rasa + Penebalan saraf + Bakteri (+)","PB = Imun baik + ringan","MB = Imun lemah + berat","Terapi = MDT 6-12 bulan+"}', '[{"id":"fc-m10-1","question":"Apa itu Kusta atau Leprosy?","answer":"Penyakit infeksi kronis yang menyerang kulit dan saraf akibat Mycobacterium leprae.","level":0},{"id":"fc-m10-2","question":"Apa penyebab utama penyakit kusta?","answer":"Mycobacterium leprae.","level":0},{"id":"fc-m10-3","question":"Organ apa yang paling sering terkena kusta?","answer":"Kulit, saraf tepi, mata, dan mukosa saluran napas.","level":0},{"id":"fc-m10-4","question":"Bagaimana cara penularan kusta?","answer":"Melalui droplet dan kontak erat jangka panjang.","level":0},{"id":"fc-m10-5","question":"Apakah kusta mudah menular?","answer":"Tidak, karena memerlukan kontak dekat dan lama.","level":0},{"id":"fc-m10-6","question":"Apa gejala khas awal kusta?","answer":"Bercak kulit mati rasa.","level":0},{"id":"fc-m10-7","question":"Mengapa penderita kusta mengalami mati rasa?","answer":"Karena bakteri merusak saraf perifer.","level":0},{"id":"fc-m10-8","question":"Sel apa yang diserang Mycobacterium leprae?","answer":"Makrofag dan sel Schwann.","level":0},{"id":"fc-m10-9","question":"Apa arti PB pada klasifikasi kusta?","answer":"Paucibacillary, bentuk ringan dengan respons imun baik.","level":0},{"id":"fc-m10-10","question":"Apa arti MB pada klasifikasi kusta?","answer":"Multibacillary, bentuk berat dengan respons imun lemah.","level":0},{"id":"fc-m10-11","question":"Sebutkan 3 tanda utama diagnosis kusta menurut WHO!","answer":"Bercak mati rasa, penebalan saraf, dan ditemukan bakteri.","level":0},{"id":"fc-m10-12","question":"Pemeriksaan penunjang untuk diagnosis kusta?","answer":"Kerokan kulit, biopsi kulit, dan tes fungsi saraf.","level":0},{"id":"fc-m10-13","question":"Apa terapi utama kusta?","answer":"Multi Drug Therapy (MDT).","level":0},{"id":"fc-m10-14","question":"Berapa lama pengobatan MDT pada kusta?","answer":"Sekitar 6 bulan hingga lebih dari 1 tahun.","level":0},{"id":"fc-m10-15","question":"Mengapa MDT menggunakan kombinasi obat?","answer":"Untuk membunuh bakteri dan mencegah resistensi.","level":0},{"id":"fc-m10-16","question":"Obat tambahan untuk reaksi peradangan kusta?","answer":"Kortikosteroid.","level":0},{"id":"fc-m10-17","question":"Mengapa fisioterapi penting pada penderita kusta?","answer":"Untuk menjaga fungsi gerak dan mencegah kecacatan.","level":0},{"id":"fc-m10-18","question":"Bagaimana pencegahan kusta?","answer":"Menjaga kebersihan, deteksi dini, dan menghindari kontak lama dengan penderita yang belum diobati.","level":0},{"id":"fc-m10-19","question":"Mengapa kasus kusta pada anak penting diperhatikan?","answer":"Karena menunjukkan penularan aktif masih terjadi.","level":0},{"id":"fc-m10-20","question":"Apa tujuan edukasi masyarakat tentang kusta?","answer":"Mengurangi stigma dan meningkatkan deteksi dini.","level":0}]', '2026-06-03T00:00:00Z'),
('m11', 'epi-penyakit-tropis', 'Bu Arlina - Kelompok 4 - Frambusia', 'Frambusia atau Yaws adalah penyakit kulit menular kronis yang disebabkan oleh bakteri Treponema pallidum subspesies pertenue. Penyakit ini termasuk kelompok treponematosis endemik dan banyak ditemukan di daerah tropis dengan sanitasi buruk. Penularan terjadi melalui kontak langsung dengan lesi kulit aktif. Jika tidak ditangani, frambusia dapat berkembang menjadi penyakit kronis yang menyebabkan deformitas dan kecacatan permanen.', '{"Frambusia","Yaws","Treponema pallidum pertenue","Treponematosis endemik","Penyakit kulit kronis","Kontak langsung kulit","Lesi aktif","Mother yaw","Daughter yaws","Papiloma","Ulkus","Osteoperiostitis","Gumma","Gangosa","Gondou","Sabre tibia","Azithromycin","Benzathine penicillin G","MDA","TCT","TTT"}', '{"Penyebab = Treponema pallidum pertenue","Penularan = Kontak kulit + Luka terbuka","Primer = Mother yaw","Sekunder = Daughter yaws","Terapi = Azithromycin dosis tunggal","Eliminasi = TCT + TTT + MDA"}', '[{"id":"fc-m11-1","question":"Apa itu Frambusia atau Yaws?","answer":"Penyakit kulit menular kronis akibat bakteri Treponema pallidum pertenue.","level":0},{"id":"fc-m11-2","question":"Frambusia termasuk kelompok penyakit apa?","answer":"Treponematosis endemik.","level":0},{"id":"fc-m11-3","question":"Siapa kelompok usia yang paling sering terkena frambusia?","answer":"Anak usia ≤15 tahun.","level":0},{"id":"fc-m11-4","question":"Di daerah seperti apa frambusia banyak ditemukan?","answer":"Daerah tropis yang hangat, lembab, dan sanitasi buruk.","level":0},{"id":"fc-m11-5","question":"Apa penyebab utama frambusia?","answer":"Treponema pallidum subspesies pertenue.","level":0},{"id":"fc-m11-6","question":"Bagaimana cara penularan frambusia?","answer":"Kontak langsung kulit dengan lesi aktif.","level":0},{"id":"fc-m11-7","question":"Apakah frambusia ditularkan melalui hubungan seksual?","answer":"Tidak.","level":0},{"id":"fc-m11-8","question":"Apa yang dimaksud mother yaw?","answer":"Lesi primer pertama di tempat masuknya bakteri.","level":0},{"id":"fc-m11-9","question":"Seperti apa bentuk lesi primer frambusia?","answer":"Papiloma atau ulkus seperti raspberry.","level":0},{"id":"fc-m11-10","question":"Apa yang dimaksud daughter yaws?","answer":"Lesi sekunder yang menyebar ke berbagai bagian tubuh.","level":0},{"id":"fc-m11-11","question":"Gejala apa yang dapat muncul pada stadium sekunder?","answer":"Papul, nodul, nyeri sendi, dan osteoperiostitis.","level":0},{"id":"fc-m11-12","question":"Apa yang terjadi pada stadium laten?","answer":"Tidak ada gejala tetapi infeksi masih ada.","level":0},{"id":"fc-m11-13","question":"Apa komplikasi stadium tersier frambusia?","answer":"Deformitas tulang dan kecacatan permanen.","level":0},{"id":"fc-m11-14","question":"Apa itu gangosa pada frambusia?","answer":"Kerusakan jaringan wajah akibat infeksi lanjut.","level":0},{"id":"fc-m11-15","question":"Pemeriksaan penunjang diagnosis frambusia?","answer":"RDT dan RPR.","level":0},{"id":"fc-m11-16","question":"Obat utama untuk pengobatan frambusia?","answer":"Azithromycin dosis tunggal.","level":0},{"id":"fc-m11-17","question":"Alternatif terapi selain azithromycin?","answer":"Benzathine penicillin G.","level":0},{"id":"fc-m11-18","question":"Apa itu strategi TCT dalam eradikasi frambusia?","answer":"Pengobatan massal seluruh komunitas.","level":0},{"id":"fc-m11-19","question":"Apa itu strategi TTT?","answer":"Pengobatan kasus dan kontak terdekat.","level":0},{"id":"fc-m11-20","question":"Bagaimana cara mencegah frambusia?","answer":"Menjaga kebersihan diri, air bersih, edukasi, dan pengobatan massal.","level":0}]', '2026-06-03T00:00:00Z'),
('m12', 'epi-penyakit-tropis', 'Bu Arlina - Kelompok 5 - Scabies', 'Scabies atau kudis adalah penyakit kulit menular akibat infestasi tungau Sarcoptes scabiei var. hominis yang hidup di lapisan kulit manusia. Penyakit ini menimbulkan gatal hebat terutama malam hari dan mudah menyebar melalui kontak erat atau penggunaan barang bersama. Faktor risiko utama meliputi personal hygiene buruk, lingkungan padat penduduk, dan sanitasi yang kurang baik. Pencegahan dilakukan dengan menjaga kebersihan diri, mengobati seluruh kontak serumah, dan membersihkan lingkungan.', '{"Scabies","Kudis","Sarcoptes scabiei var hominis","Tungau kulit","Stratum korneum","Gatal hebat","Terowongan kulit","Kontak erat","Skin scraping","Reaksi hipersensitivitas tipe IV","Personal hygiene buruk","Reinfestasi","Carrier","Postscabietic itch","Antihistamin","Sanitasi lingkungan","Air hangat","Sprei dan handuk"}', '{"Penyebab = Sarcoptes scabiei","Penularan = Kontak langsung + Barang bersama","Siklus hidup = 10-14 hari","Diagnosis = Gatal + Liang + Skin scraping","Pencegahan = Obati semua kontak + Cuci pakaian + Kebersihan diri"}', '[{"id":"fc-m12-1","question":"Apa itu Scabies atau kudis?","answer":"Penyakit kulit menular akibat infestasi tungau Sarcoptes scabiei.","level":0},{"id":"fc-m12-2","question":"Apa penyebab utama scabies?","answer":"Sarcoptes scabiei var. hominis.","level":0},{"id":"fc-m12-3","question":"Di bagian kulit mana tungau scabies hidup?","answer":"Stratum korneum kulit.","level":0},{"id":"fc-m12-4","question":"Apa gejala utama scabies?","answer":"Gatal hebat terutama pada malam hari.","level":0},{"id":"fc-m12-5","question":"Bagaimana cara penularan scabies?","answer":"Kontak langsung dan penggunaan barang bersama.","level":0},{"id":"fc-m12-6","question":"Berapa lama kontak kulit yang meningkatkan risiko penularan?","answer":"Sekitar 15-20 menit atau lebih.","level":0},{"id":"fc-m12-7","question":"Berapa lama tungau dapat bertahan di luar tubuh manusia?","answer":"Sekitar 24-36 jam.","level":0},{"id":"fc-m12-8","question":"Apa faktor risiko utama scabies?","answer":"Hygiene buruk, lingkungan padat, sanitasi buruk.","level":0},{"id":"fc-m12-9","question":"Berapa lama siklus hidup tungau scabies?","answer":"Sekitar 10-14 hari.","level":0},{"id":"fc-m12-10","question":"Lesi khas scabies berbentuk seperti apa?","answer":"Terowongan kecil berbentuk koma.","level":0},{"id":"fc-m12-11","question":"Lokasi khas lesi scabies?","answer":"Sela jari, pusar, area genital, dan kulit tipis lainnya.","level":0},{"id":"fc-m12-12","question":"Mengapa scabies menyebabkan gatal?","answer":"Karena reaksi hipersensitivitas terhadap tungau.","level":0},{"id":"fc-m12-13","question":"Apa pemeriksaan konfirmasi scabies?","answer":"Skin scraping untuk menemukan tungau, telur, atau feses.","level":0},{"id":"fc-m12-14","question":"Mengapa semua penghuni rumah perlu diobati?","answer":"Untuk mencegah reinfestasi dan carrier tanpa gejala.","level":0},{"id":"fc-m12-15","question":"Berapa cepat gejala biasanya membaik setelah terapi?","answer":"Sekitar 3 hari.","level":0},{"id":"fc-m12-16","question":"Apa itu postscabietic itch?","answer":"Gatal yang masih bertahan setelah pengobatan berhasil.","level":0},{"id":"fc-m12-17","question":"Berapa lama postscabietic itch dapat berlangsung?","answer":"Hingga sekitar 4 minggu.","level":0},{"id":"fc-m12-18","question":"Bagaimana cara membersihkan pakaian penderita scabies?","answer":"Dicuci menggunakan air hangat dan sabun.","level":0},{"id":"fc-m12-19","question":"Apa yang dilakukan pada barang yang tidak dapat dicuci?","answer":"Disimpan dalam plastik tertutup sekitar 2 minggu.","level":0},{"id":"fc-m12-20","question":"Bagaimana cara mencegah scabies?","answer":"Menjaga kebersihan, menghindari kontak erat, dan membersihkan lingkungan.","level":0}]', '2026-06-03T00:00:00Z'),
('m13', 'epi-penyakit-tropis', 'Pak Amri - Kelompok 1 - Campak', 'Campak (measles) adalah penyakit infeksi sangat menular yang disebabkan oleh virus campak dari genus Morbillivirus. Penyakit ini menyerang sistem pernapasan dan menyebar ke seluruh tubuh melalui aliran darah. Campak dapat menyebabkan komplikasi serius seperti pneumonia, ensefalitis, kebutaan, hingga kematian terutama pada anak kecil dan individu dengan sistem imun rendah. Pencegahan utama dilakukan melalui imunisasi MR/MMR dan pengendalian kasus secara cepat.', '{"Campak","Measles","Rubeola","Morbillivirus","Paramyxoviridae","Droplet pernapasan","Ruam makulopapular","Bercak Koplik","Batuk","Coryza","Konjungtivitis","IgM anti campak","PCR virus","Vitamin A","MR vaccine","MMR vaccine","Herd immunity","Isolasi pasien"}', '{"Penyebab = Morbillivirus","Triad Campak = Batuk + Coryza + Konjungtivitis","Inkubasi = 7-18 hari","Penularan = 5 hari sebelum sampai 4 hari sesudah ruam","Pencegahan = MR/MMR + Herd immunity ≥95%","Terapi = Supportif + Vitamin A"}', '[{"id":"fc-m13-1","question":"Apa itu campak (measles)?","answer":"Penyakit infeksi menular akibat virus campak yang menyerang sistem pernapasan.","level":0},{"id":"fc-m13-2","question":"Virus penyebab campak termasuk genus apa?","answer":"Morbillivirus.","level":0},{"id":"fc-m13-3","question":"Virus campak termasuk keluarga apa?","answer":"Paramyxoviridae.","level":0},{"id":"fc-m13-4","question":"Bagaimana campak menyebar dalam tubuh?","answer":"Dari saluran napas lalu menyebar melalui aliran darah.","level":0},{"id":"fc-m13-5","question":"Siapa yang berisiko mengalami komplikasi berat campak?","answer":"Anak kecil dan individu dengan daya tahan tubuh rendah.","level":0},{"id":"fc-m13-6","question":"Sebutkan komplikasi campak!","answer":"Pneumonia, ensefalitis, kebutaan, gizi buruk, dan kematian.","level":0},{"id":"fc-m13-7","question":"Berapa masa inkubasi campak?","answer":"Sekitar 7 sampai 18 hari.","level":0},{"id":"fc-m13-8","question":"Berapa lama masa prodromal campak?","answer":"Sekitar 4 hari.","level":0},{"id":"fc-m13-9","question":"Kapan penderita campak dapat menularkan penyakit?","answer":"5 hari sebelum hingga 4 hari setelah ruam muncul.","level":0},{"id":"fc-m13-10","question":"Apa tiga gejala utama (triad) campak?","answer":"Batuk, pilek (coryza), dan konjungtivitis.","level":0},{"id":"fc-m13-11","question":"Bagaimana pola penyebaran ruam campak?","answer":"Dari wajah ke leher, badan, lalu ekstremitas.","level":0},{"id":"fc-m13-12","question":"Apa itu bercak Koplik?","answer":"Bercak putih keabuan di mukosa mulut yang khas pada campak.","level":0},{"id":"fc-m13-13","question":"Pemeriksaan laboratorium untuk konfirmasi campak?","answer":"IgM anti campak dan PCR virus.","level":0},{"id":"fc-m13-14","question":"Apakah ada antivirus khusus untuk campak?","answer":"Tidak ada, terapi bersifat suportif.","level":0},{"id":"fc-m13-15","question":"Mengapa vitamin A diberikan pada penderita campak?","answer":"Untuk mengurangi komplikasi terutama pada mata.","level":0},{"id":"fc-m13-16","question":"Obat yang digunakan untuk menurunkan demam campak?","answer":"Paracetamol.","level":0},{"id":"fc-m13-17","question":"Kapan antibiotik diberikan pada campak?","answer":"Jika terdapat infeksi sekunder bakteri.","level":0},{"id":"fc-m13-18","question":"Apa vaksin untuk mencegah campak?","answer":"MR atau MMR.","level":0},{"id":"fc-m13-19","question":"Berapa cakupan imunisasi yang diperlukan untuk herd immunity?","answer":"Minimal 95%.","level":0},{"id":"fc-m13-20","question":"Mengapa pasien campak perlu diisolasi?","answer":"Karena sangat mudah menular selama periode infeksi.","level":0}]', '2026-06-03T00:00:00Z'),
('m14', 'epi-penyakit-tropis', 'Pak Amri - Kelompok 2 - Polio', 'Polio atau poliomielitis adalah penyakit infeksi yang disebabkan oleh poliovirus yang menyerang sistem saraf dan dapat menyebabkan kelumpuhan permanen. Virus ini sangat menular and menyebar terutama melalui jalur fecal oral serta droplet. Sebagian besar infeksi tidak menunjukkan gejala, namun pada kasus berat dapat menyebabkan kelumpuhan akut, gangguan pernapasan, bahkan kematian. Pencegahan utama dilakukan melalui imunisasi lengkap dan penguatan surveilans.', '{"Polio","Poliomielitis","Poliovirus","Enterovirus","Picornaviridae","Fecal oral","Droplet","Viremia","Neuron motorik","Acute Flaccid Paralysis","AFP","Paralisis flaksid akut","OPV","IPV","Vaccine Derived Poliovirus","VDPV2","Imunisasi dasar","PIN Polio"}', '{"Penyebab = Poliovirus","Penularan = Fecal oral + Droplet","Target utama = Neuron motorik","Pencegahan = OPV + IPV","Surveilans = AFP","Risiko tinggi = Anak <5 tahun + imunisasi tidak lengkap"}', '[{"id":"fc-m14-1","question":"Apa itu polio?","answer":"Penyakit infeksi akibat poliovirus yang dapat menyerang sistem saraf.","level":0},{"id":"fc-m14-2","question":"Apa penyebab penyakit polio?","answer":"Poliovirus.","level":0},{"id":"fc-m14-3","question":"Poliovirus termasuk genus apa?","answer":"Enterovirus.","level":0},{"id":"fc-m14-4","question":"Poliovirus termasuk keluarga apa?","answer":"Picornaviridae.","level":0},{"id":"fc-m14-5","question":"Bagaimana cara utama penularan polio?","answer":"Melalui fecal oral and droplet.","level":0},{"id":"fc-m14-6","question":"Dari mana poliovirus banyak keluar dari tubuh penderita?","answer":"Dari tinja penderita.","level":0},{"id":"fc-m14-7","question":"Kelompok usia paling rentan terkena polio?","answer":"Anak usia di bawah 5 tahun.","level":0},{"id":"fc-m14-8","question":"Faktor risiko utama polio?","answer":"Imunisasi yang tidak lengkap.","level":0},{"id":"fc-m14-9","question":"Di mana poliovirus pertama kali bereplikasi?","answer":"Orofaring dan usus halus.","level":0},{"id":"fc-m14-10","question":"Apa yang dimaksud viremia pada polio?","answer":"Masuknya virus ke aliran darah.","level":0},{"id":"fc-m14-11","question":"Bagian sistem saraf apa yang terutama diserang poliovirus?","answer":"Neuron motorik pada medula spinalis dan batang otak.","level":0},{"id":"fc-m14-12","question":"Apa komplikasi serius polio?","answer":"Kelumpuhan flaksid akut dan gangguan pernapasan.","level":0},{"id":"fc-m14-13","question":"Berapa masa inkubasi polio?","answer":"Sekitar 3 sampai 6 hari.","level":0},{"id":"fc-m14-14","question":"Kapan gejala polio biasanya muncul setelah infeksi?","answer":"Sekitar 7 sampai 21 hari.","level":0},{"id":"fc-m14-15","question":"Apa gejala ringan polio?","answer":"Demam, sakit tenggorokan, sakit kepala, dan nyeri perut.","level":0},{"id":"fc-m14-16","question":"Apa bentuk polio yang menyebabkan kelumpuhan?","answer":"Poliomielitis paralitik.","level":0},{"id":"fc-m14-17","question":"Apa itu AFP pada surveilans polio?","answer":"Acute Flaccid Paralysis atau kelumpuhan layuh akut.","level":0},{"id":"fc-m14-18","question":"Apa dua jenis vaksin polio?","answer":"OPV dan IPV.","level":0},{"id":"fc-m14-19","question":"Apa tujuan Pekan Imunisasi Nasional (PIN)?","answer":"Meningkatkan cakupan imunisasi untuk mencegah wabah polio.","level":0},{"id":"fc-m14-20","question":"Mengapa polio lebih mudah menyebar di daerah sanitasi buruk?","answer":"Karena virus dapat mencemari makanan, air, dan lingkungan dengan mudah.","level":0}]', '2026-06-03T00:00:00Z'),
('m15', 'epi-penyakit-tropis', 'Pak Amri - Kelompok 3 - Gondongan', 'Gondongan atau mumps adalah penyakit infeksi akut yang disebabkan oleh paramyxovirus dan ditandai dengan pembengkakan kelenjar parotis. Penyakit ini terutama menyerang anak-anak dan dewasa muda serta menular melalui droplet dan kontak erat. Gejala khas berupa pembengkakan pipi atau rahang disertai demam dan nyeri. Pencegahan utama dilakukan melalui imunisasi MMR dan penerapan perilaku hidup bersih.', '{"Gondongan","Mumps","Paramyxovirus","Parotitis","Kelenjar parotis","Droplet","Saluran pernapasan atas","Viremia","RT-PCR","IgM","IgG","MMR","Pembengkakan pipi","Nyeri rahang","Saliva","Swab bukal","Etika batuk","Anak usia sekolah"}', '{"Penyebab = Paramyxovirus","Penularan = Droplet + Kontak erat","Gejala khas = Parotitis + Demam + Nyeri","Diagnosis = Gejala khas + RT-PCR","Pencegahan = MMR + Cuci tangan + Etika batuk"}', '[{"id":"fc-m15-1","question":"Apa itu gondongan atau mumps?","answer":"Penyakit infeksi akut akibat paramyxovirus yang menyerang kelenjar ludah.","level":0},{"id":"fc-m15-2","question":"Apa penyebab penyakit gondongan?","answer":"Paramyxovirus.","level":0},{"id":"fc-m15-3","question":"Apa gejala khas gondongan?","answer":"Pembengkakan kelenjar parotis.","level":0},{"id":"fc-m15-4","question":"Di mana letak kelenjar parotis?","answer":"Di antara telinga dan rahang.","level":0},{"id":"fc-m15-5","question":"Bagaimana cara penularan gondongan?","answer":"Melalui droplet dan kontak erat.","level":0},{"id":"fc-m15-6","question":"Siapa kelompok usia yang paling sering menyebarkan gondongan?","answer":"Anak usia sekolah 6-14 tahun.","level":0},{"id":"fc-m15-7","question":"Apa faktor risiko utama gondongan?","answer":"Tidak mendapatkan vaksin MMR.","level":0},{"id":"fc-m15-8","question":"Kelompok usia yang rentan terkena gondongan?","answer":"Anak usia 2-12 tahun.","level":0},{"id":"fc-m15-9","question":"Di mana virus gondongan pertama kali bereplikasi?","answer":"Nasofaring dan kelenjar getah bening regional.","level":0},{"id":"fc-m15-10","question":"Apa yang dimaksud viremia pada gondongan?","answer":"Penyebaran virus melalui aliran darah.","level":0},{"id":"fc-m15-11","question":"Organ apa saja yang dapat terkena penyebaran virus gondongan?","answer":"Parotis, sistem saraf pusat, pankreas, dan testis.","level":0},{"id":"fc-m15-12","question":"Apa itu parotitis?","answer":"Peradangan dan pembengkakan kelenjar parotis.","level":0},{"id":"fc-m15-13","question":"Gejala prodromal gondongan?","answer":"Demam, sakit kepala, nyeri otot, dan malaise.","level":0},{"id":"fc-m15-14","question":"Pemeriksaan laboratorium paling sensitif untuk gondongan?","answer":"RT-PCR.","level":0},{"id":"fc-m15-15","question":"Sampel apa yang dapat digunakan untuk pemeriksaan gondongan?","answer":"Swab bukal, saliva, atau urin.","level":0},{"id":"fc-m15-16","question":"Apa fungsi pemeriksaan IgM dan IgG pada gondongan?","answer":"Membantu konfirmasi infeksi.","level":0},{"id":"fc-m15-17","question":"Apa vaksin untuk mencegah gondongan?","answer":"Vaksin MMR.","level":0},{"id":"fc-m15-18","question":"Kapan jadwal vaksin MMR untuk gondongan?","answer":"Usia 18 bulan dan 5-7 tahun.","level":0},{"id":"fc-m15-19","question":"Selain vaksin, bagaimana cara mencegah gondongan?","answer":"Cuci tangan, etika batuk, dan tidak berbagi alat makan.","level":0},{"id":"fc-m15-20","question":"Bagaimana prinsip pengobatan gondongan?","answer":"Bersifat suportif untuk meredakan gejala.","level":0}]', '2026-06-03T00:00:00Z'),
('m16', 'epi-penyakit-tropis', 'Pak Amri - Kelompok 4 - Meningitis', 'Meningitis adalah peradangan pada meninges atau selaput pelindung otak dan sumsum tulang belakang yang dapat disebabkan oleh bakteri, virus, jamur, maupun parasit. Penyakit ini termasuk kondisi gawat darurat karena dapat berkembang cepat dan menyebabkan komplikasi serius hingga kematian. Gejala khas meliputi demam tinggi, sakit kepala, dan leher kaku. Penanganan cepat dan pencegahan melalui vaksinasi sangat penting untuk mengurangi risiko komplikasi.', '{"Meningitis","Meninges","Peradangan otak","Neisseria meningitidis","Streptococcus pneumoniae","Haemophilus influenzae","Enterovirus","Herpes virus","Cryptococcus","Leher kaku","Pungsi lumbal","Cairan serebrospinal","Droplet","Antibiotik intravena","Tekanan intrakranial","Vaksin Hib","Vaksin pneumokokus","Vaksin meningokokus"}', '{"Penyebab = Bakteri + Virus + Jamur + Parasit","Gejala khas = Demam + Leher kaku + Sakit kepala","Diagnosis utama = Pungsi lumbal","Penularan = Droplet + Kontak erat","Pencegahan = Vaksin + Kebersihan + Etika batuk"}', '[{"id":"fc-m16-1","question":"Apa itu meningitis?","answer":"Peradangan pada meninges atau selaput pelindung otak dan sumsum tulang belakang.","level":0},{"id":"fc-m16-2","question":"Mengapa meningitis termasuk kondisi gawat darurat?","answer":"Karena dapat berkembang cepat dan menyebabkan komplikasi serius hingga kematian.","level":0},{"id":"fc-m16-3","question":"Apa penyebab paling umum meningitis?","answer":"Bakteri, virus, jamur, dan parasit.","level":0},{"id":"fc-m16-4","question":"Apa jenis meningitis yang paling berbahaya?","answer":"Meningitis bakteri.","level":0},{"id":"fc-m16-5","question":"Sebutkan tiga bakteri penyebab meningitis!","answer":"Neisseria meningitidis, Streptococcus pneumoniae, dan Haemophilus influenzae.","level":0},{"id":"fc-m16-6","question":"Apa gejala khas meningitis?","answer":"Leher kaku.","level":0},{"id":"fc-m16-7","question":"Apa gejala umum meningitis selain leher kaku?","answer":"Demam tinggi, sakit kepala, mual, muntah, dan sensitif cahaya.","level":0},{"id":"fc-m16-8","question":"Bagaimana cara meningitis menular?","answer":"Melalui droplet dan kontak erat.","level":0},{"id":"fc-m16-9","question":"Siapa yang lebih berisiko terkena meningitis?","answer":"Bayi, anak-anak, dan individu dengan imun rendah.","level":0},{"id":"fc-m16-10","question":"Mengapa lingkungan padat meningkatkan risiko meningitis?","answer":"Karena mempermudah penularan droplet.","level":0},{"id":"fc-m16-11","question":"Apa pemeriksaan utama untuk memastikan meningitis?","answer":"Pungsi lumbal.","level":0},{"id":"fc-m16-12","question":"Apa yang diperiksa saat pungsi lumbal?","answer":"Cairan serebrospinal.","level":0},{"id":"fc-m16-13","question":"Apa tujuan CT Scan atau MRI pada meningitis?","answer":"Membantu evaluasi komplikasi atau kondisi neurologis.","level":0},{"id":"fc-m16-14","question":"Bagaimana pengobatan meningitis virus?","answer":"Istirahat, cairan cukup, dan terapi simptomatik.","level":0},{"id":"fc-m16-15","question":"Bagaimana pengobatan meningitis bakteri?","answer":"Antibiotik intravena dan perawatan intensif.","level":0},{"id":"fc-m16-16","question":"Apa komplikasi meningitis?","answer":"Kejang, gangguan pendengaran, kerusakan otak, hingga kematian.","level":0},{"id":"fc-m16-17","question":"Mengapa tekanan intrakranial meningkat pada meningitis?","answer":"Karena proses inflamasi pada meninges.","level":0},{"id":"fc-m16-18","question":"Apa vaksin yang dapat mencegah meningitis?","answer":"Hib, pneumokokus, dan meningokokus.","level":0},{"id":"fc-m16-19","question":"Bagaimana cara mencegah meningitis selain vaksinasi?","answer":"Menjaga kebersihan tangan dan menghindari kontak dekat.","level":0},{"id":"fc-m16-20","question":"Mengapa diagnosis cepat penting pada meningitis?","answer":"Untuk mencegah komplikasi permanen dan kematian.","level":0}]', '2026-06-03T00:00:00Z'),
('m17', 'epi-penyakit-tropis', 'Pak Amri - Kelompok 5 - TBC', 'Tuberkulosis (TBC) adalah penyakit infeksi menular yang disebabkan oleh bakteri Mycobacterium tuberculosis yang menyerang terutama paru-paru dan ditularkan melalui udara. Penyakit ini masih menjadi masalah kesehatan global karena tingginya angka kasus dan kematian. Gejala utama berupa batuk berkepanjangan disertai penurunan berat badan, demam, dan keringat malam. Pengobatan membutuhkan kombinasi obat jangka panjang dan kepatuhan tinggi untuk mencegah resistensi obat.', '{"Tuberkulosis","TBC","Mycobacterium tuberculosis","Bakteri tahan asam","BTA","Airborne transmission","Droplet aerosol","Alveoli","TB laten","TB aktif","IGRA","Mantoux","Rontgen dada","DOT","PMO","Isoniazid","Rifampin","Ethambutol","Pyrazinamide","BCG"}', '{"Penyebab = Mycobacterium tuberculosis","Penularan = Airborne + Droplet aerosol","Gejala utama = Batuk ≥2 minggu","TB laten = Tidak menular","Terapi = OAT 4-9 bulan","Pencegahan = BCG + Ventilasi + Masker + TPT"}', '[{"id":"fc-m17-1","question":"Apa itu Tuberkulosis (TBC)?","answer":"Penyakit infeksi menular akibat Mycobacterium tuberculosis.","level":0},{"id":"fc-m17-2","question":"Apa penyebab utama TBC?","answer":"Mycobacterium tuberculosis.","level":0},{"id":"fc-m17-3","question":"Bagaimana cara penularan TBC?","answer":"Melalui udara dalam bentuk droplet aerosol.","level":0},{"id":"fc-m17-4","question":"Apa arti BTA pada TBC?","answer":"Bakteri Tahan Asam.","level":0},{"id":"fc-m17-5","question":"Organ apa yang paling sering terkena TBC?","answer":"Paru-paru.","level":0},{"id":"fc-m17-6","question":"Di mana bakteri TB pertama kali mencapai setelah terhirup?","answer":"Alveoli paru.","level":0},{"id":"fc-m17-7","question":"Apa itu TB laten?","answer":"Kondisi saat bakteri ada dalam tubuh tetapi tidak aktif dan tidak menular.","level":0},{"id":"fc-m17-8","question":"Apa yang dapat menyebabkan TB laten menjadi aktif?","answer":"Penurunan daya tahan tubuh.","level":0},{"id":"fc-m17-9","question":"Gejala utama TBC?","answer":"Batuk berdahak selama 2 minggu atau lebih.","level":0},{"id":"fc-m17-10","question":"Gejala tambahan TBC?","answer":"Demam, berat badan turun, keringat malam, sesak, dan lemas.","level":0},{"id":"fc-m17-11","question":"Siapa kelompok berisiko tinggi terkena TBC?","answer":"Bayi, lansia, penderita HIV, diabetes, dan perokok.","level":0},{"id":"fc-m17-12","question":"Pemeriksaan apa yang digunakan untuk skrining infeksi TB?","answer":"IGRA dan Mantoux.","level":0},{"id":"fc-m17-13","question":"Mengapa rontgen dada dilakukan pada TBC?","answer":"Untuk membantu melihat gambaran kelainan paru.","level":0},{"id":"fc-m17-14","question":"Apa tujuan pemeriksaan dahak pada TBC?","answer":"Mengidentifikasi keberadaan bakteri TB.","level":0},{"id":"fc-m17-15","question":"Sebutkan obat utama terapi TBC!","answer":"Isoniazid, Rifampin, Ethambutol, dan Pyrazinamide.","level":0},{"id":"fc-m17-16","question":"Berapa lama pengobatan TB aktif biasanya berlangsung?","answer":"Sekitar 4 sampai 9 bulan.","level":0},{"id":"fc-m17-17","question":"Mengapa obat TBC harus diminum sampai selesai?","answer":"Untuk mencegah resistensi obat.","level":0},{"id":"fc-m17-18","question":"Apa itu DOT pada pengobatan TBC?","answer":"Pengawasan langsung minum obat oleh petugas atau PMO.","level":0},{"id":"fc-m17-19","question":"Apa vaksin untuk mencegah TBC pada anak?","answer":"Vaksin BCG.","level":0},{"id":"fc-m17-20","question":"Bagaimana cara mencegah penularan TBC?","answer":"Menggunakan masker, ventilasi baik, etika batuk, dan deteksi dini.","level":0}]', '2026-06-03T00:00:00Z'),
('m18', 'epi-penyakit-tropis', 'Pak Amri - Kelompok 6 - Hepatitis', 'Hepatitis adalah peradangan pada organ hati yang dapat disebabkan oleh virus, autoimun, obat-obatan, alkohol, maupun faktor lainnya. Penyebab tersering adalah infeksi virus hepatitis A, B, C, D, dan E yang memiliki jalur penularan berbeda. Penyakit ini dapat berkembang menjadi kronis dan menyebabkan sirosis hingga kanker hati apabila tidak ditangani dengan baik. Pencegahan utama dilakukan melalui vaksinasi, perilaku hidup bersih, dan menghindari faktor risiko penularan.', '{"Hepatitis","Peradangan hati","Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis D","Hepatitis E","Hepatovirus","Hepadnaviridae","Flaviviridae","Deltavirus","Fecal oral","Ikterus","Sirosis","Kanker hati","HBsAg","Anti HAV IgM","Anti HCV","PCR","DAA"}', '{"HAV = Fecal oral","HBV = Darah + Cairan tubuh","HCV = Jarum + Darah","HDV = Butuh HBV","HEV = Sanitasi buruk + Air tercemar","Komplikasi = Sirosis + Kanker hati","Pencegahan = Vaksin + Higiene + Jarum steril"}', '[{"id":"fc-m18-1","question":"Apa itu hepatitis?","answer":"Peradangan pada organ hati.","level":0},{"id":"fc-m18-2","question":"Apa penyebab tersering hepatitis?","answer":"Infeksi virus hepatitis.","level":0},{"id":"fc-m18-3","question":"Berapa jumlah strain utama virus hepatitis?","answer":"Lima strain utama yaitu A, B, C, D, dan E.","level":0},{"id":"fc-m18-4","question":"Bagaimana penularan Hepatitis A?","answer":"Melalui jalur fecal oral.","level":0},{"id":"fc-m18-5","question":"Bagaimana penularan Hepatitis B?","answer":"Melalui darah and cairan tubuh.","level":0},{"id":"fc-m18-6","question":"Bagaimana penularan Hepatitis C?","answer":"Melalui darah, jarum suntik, dan alat tajam terkontaminasi.","level":0},{"id":"fc-m18-7","question":"Mengapa Hepatitis D unik dibandingkan tipe lain?","answer":"Karena membutuhkan Hepatitis B untuk bereplikasi.","level":0},{"id":"fc-m18-8","question":"Bagaimana Hepatitis E dapat ditularkan?","answer":"Melalui fecal oral dan makanan hewani mentah/setengah matang.","level":0},{"id":"fc-m18-9","question":"Apa komplikasi jangka panjang hepatitis kronis?","answer":"Sirosis dan kanker hati.","level":0},{"id":"fc-m18-10","question":"Apa gejala umum hepatitis?","answer":"Demam, mual, muntah, nyeri perut, dan lemas.","level":0},{"id":"fc-m18-11","question":"Apa yang dimaksud ikterus?","answer":"Kondisi kulit dan mata menjadi kuning.","level":0},{"id":"fc-m18-12","question":"Mengapa urin penderita hepatitis sering berwarna gelap?","answer":"Karena gangguan fungsi hati dan metabolisme bilirubin.","level":0},{"id":"fc-m18-13","question":"Pemeriksaan laboratorium untuk Hepatitis A?","answer":"Anti HAV IgM.","level":0},{"id":"fc-m18-14","question":"Pemeriksaan utama Hepatitis B?","answer":"HBsAg, anti HBc, dan HBV DNA.","level":0},{"id":"fc-m18-15","question":"Pemeriksaan utama Hepatitis C?","answer":"Anti HCV dan HCV RNA/PCR.","level":0},{"id":"fc-m18-16","question":"Bagaimana pengobatan Hepatitis A dan E?","answer":"Bersifat suportif dengan istirahat dan nutrisi.","level":0},{"id":"fc-m18-17","question":"Apa terapi utama Hepatitis C modern?","answer":"Direct Acting Antiviral (DAA).","level":0},{"id":"fc-m18-18","question":"Bagaimana pencegahan utama Hepatitis B?","answer":"Vaksinasi dan menghindari paparan darah terkontaminasi.","level":0},{"id":"fc-m18-19","question":"Mengapa vaksin Hepatitis B dapat mencegah Hepatitis D?","answer":"Karena HDV membutuhkan HBV untuk berkembang.","level":0},{"id":"fc-m18-20","question":"Bagaimana cara mencegah Hepatitis A dan E?","answer":"Menjaga sanitasi, air bersih, dan kebersihan makanan.","level":0}]', '2026-06-03T00:00:00Z')
